async connectServer(name, config) {
  try {
    const url = config.url;
    let safeUrl = url;
    try {
      const u = new URL(url);
      u.password = '';
      u.username = '';
      safeUrl = u.toString();
    } catch (e) {
      // invalid url, just keep it as is or mask it
    }
    this.logger.info(`[MCP] Connecting to ${name} at ${safeUrl}`);

  const contentType = response.headers.get('content-type') || '';

  if (contentType.includes('text/event-stream')) {
    // POST response is SSE - parse it
    await this._readSseResponse(response.body);
  } else if (contentType.includes('application/json')) {
    const data = await response.json();
    if (this._debug) console.log('[Transport] JSON response');
    const messages = Array.isArray(data) ? data : [data];
    for (const msg of messages) {
      if (this.onmessage) this.onmessage(msg);
    }
  } else {
    // Try to consume and release
    if (response.body) await response.body.cancel().catch(() => {});
  }
} catch (error) {
